    cleaned = normalize_whitespace(text)
    if len(cleaned) <= max_chars:
        return cleaned

    words = cleaned.split()
    if not words:
        return ""

    current_text = ""
    for word in words:
        if not current_text:
            test_text = word
        else:
            test_text = current_text + " " + word

        if len(test_text) + len(ellipsis) <= max_chars:
            current_text = test_text
        else:
            break

    if current_text:
        return current_text + ellipsis

    return words[0][:max_chars]"
  }
